using UnityEngine;

namespace GodGame.Rendering
{
    /// <summary>
    /// Pre-baked Vertex Animation Texture data for a unit mesh: stores vertex positions and normals in upright root
    /// space (+Y up, -Z forward, feet at Y = 0) across <see cref="FrameCount"/> looping frames.
    /// Generated by the editor VAT baker; read by <see cref="UnitCapsuleRenderer"/> and sampled in DebugUnits.shader.
    /// </summary>
    public sealed class UnitVatData : ScriptableObject
    {
        public int ClipCount = 1;
        public int FramesPerClip = 30;
        public int FrameCount;
        public int VertexCount;
        public float Fps = 30f;

        /// <summary>Row-major [frame * VertexCount + vertex] positions (xyz in metres, w = 1).</summary>
        public Vector4[] Positions;

        /// <summary>Row-major [frame * VertexCount + vertex] unit normals (xyz, w = 0).</summary>
        public Vector4[] Normals;
    }
}
